#include <string.h>

#define MAXN 105
#define MAXM 105
#define INF 1000000000

/*
Assumed standard grid encoding:
'.' : empty
'#' : obstacle
'S' : laser generator
'T' : creature (target)

Input format:
N M A
N lines of M characters

We need minimum mirrors, with at most A of type P and at most A of type Q.

Directions:
0 = up, 1 = right, 2 = down, 3 = left

Mirror effects:
Type P: "\" shape
  up->left, left->up, right->down, down->right
Type Q: "/" shape
  up->right, right->up, down->left, left->down

Since generator direction is fixed but not explicitly given in the statement text here,
we consider the beam may start in any of the 4 directions from S.
This matches the usual interpretation when only generator location is marked.
If the original judge includes direction in the map, this code would need adaptation.
*/

typedef struct {
    short x, y, d, p, q;
} State;

static char g[MAXN][MAXM];
static unsigned char vis[MAXN][MAXM][4][11][11];

static State queue_arr[100 * 100 * 4 * 11 * 11 + 5];
static int dx[4] = {-1, 0, 1, 0};
static int dy[4] = {0, 1, 0, -1};

int reflectP(int d) { /* "\" */
    if (d == 0) return 3;
    if (d == 3) return 0;
    if (d == 1) return 2;
    return 1; /* d == 2 */
}

int reflectQ(int d) { /* "/" */
    if (d == 0) return 1;
    if (d == 1) return 0;
    if (d == 2) return 3;
    return 2; /* d == 3 */
}

int main(void) {
    int N, M, A;
    if (scanf("%d %d %d", &N, &M, &A) != 3) return 0;

    int sx = -1, sy = -1, tx = -1, ty = -1;
    for (int i = 0; i < N; i++) {
        scanf("%s", g[i]);
        for (int j = 0; j < M; j++) {
            if (g[i][j] == 'S') {
                sx = i; sy = j;
            } else if (g[i][j] == 'T') {
                tx = i; ty = j;
            }
        }
    }

    memset(vis, 0, sizeof(vis));

    int head = 0, tail = 0;

    for (int d = 0; d < 4; d++) {
        vis[sx][sy][d][0][0] = 1;
        queue_arr[tail++] = (State){sx, sy, d, 0, 0};
    }

    while (head < tail) {
        State cur = queue_arr[head++];

        if (cur.x == tx && cur.y == ty) {
            printf("%d\n", cur.p + cur.q);
            return 0;
        }

        int nx = cur.x + dx[cur.d];
        int ny = cur.y + dy[cur.d];

        if (nx < 0 || nx >= N || ny < 0 || ny >= M) continue;
        if (g[nx][ny] == '#') continue;

        /* Move straight without placing mirror */
        if (!vis[nx][ny][cur.d][cur.p][cur.q]) {
            vis[nx][ny][cur.d][cur.p][cur.q] = 1;
            queue_arr[tail++] = (State){nx, ny, cur.d, cur.p, cur.q};
        }

        /* Can place mirrors only not on S or T */
        if (g[nx][ny] != 'S' && g[nx][ny] != 'T') {
            if (cur.p < A) {
                int nd = reflectP(cur.d);
                if (!vis[nx][ny][nd][cur.p + 1][cur.q]) {
                    vis[nx][ny][nd][cur.p + 1][cur.q] = 1;
                    queue_arr[tail++] = (State){nx, ny, nd, cur.p + 1, cur.q};
                }
            }
            if (cur.q < A) {
                int nd = reflectQ(cur.d);
                if (!vis[nx][ny][nd][cur.p][cur.q + 1]) {
                    vis[nx][ny][nd][cur.p][cur.q + 1] = 1;
                    queue_arr[tail++] = (State){nx, ny, nd, cur.p, cur.q + 1};
                }
            }
        }
    }

    printf("-1\n");
    return 0;
}

