int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, A;
    cin >> N >> M >> A;

    vector<string> g(N);
    for (int i = 0; i < N; ++i) cin >> g[i];

    // Assumed symbols:
    // S: laser generator
    // T: creature
    // #: obstacle
    // .: empty
    //
    // The beam direction is fixed by the generator symbol:
    // > < ^ v
    // If the input instead uses S plus some other convention, this problem
    // statement would be incomplete; here we support directional generator chars.
    pair<int,int> start = {-1,-1}, target = {-1,-1};
    int startDir = -1;

    auto dirOf = [&](char c)->int{
        if (c == '^') return 0;
        if (c == '>') return 1;
        if (c == 'v') return 2;
        if (c == '<') return 3;
        return -1;
    };

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            char c = g[i][j];
            if (c == 'C' || c == 'T') target = {i, j};
            int d = dirOf(c);
            if (d != -1) {
                start = {i, j};
                startDir = d;
            }
        }
    }

    if (start.first == -1 || target.first == -1) {
        // Fallback: maybe input uses S and E/C with separate direction not present.
        // Since statement provided here does not define exact symbols, fail safely.
        cout << "impossible\n";
        return 0;
    }

    const int dx[4] = {-1, 0, 1, 0};
    const int dy[4] = {0, 1, 0, -1};

    // Reflection:
    // P mirror: "/" shape
    //   up->right, right->up, down->left, left->down
    // Q mirror: "\" shape
    //   up->left, left->up, down->right, right->down
    auto reflectP = [&](int d)->int{
        if (d == 0) return 1;
        if (d == 1) return 0;
        if (d == 2) return 3;
        return 2;
    };
    auto reflectQ = [&](int d)->int{
        if (d == 0) return 3;
        if (d == 3) return 0;
        if (d == 2) return 1;
        return 2;
    };

    const int INF = 1e9;
    static int dist[100][100][4][11][11];
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < M; ++j)
            for (int d = 0; d < 4; ++d)
                for (int p = 0; p <= A; ++p)
                    for (int q = 0; q <= A; ++q)
                        dist[i][j][d][p][q] = INF;

    deque<State> dq;
    dist[start.first][start.second][startDir][0][0] = 0;
    dq.push_back({start.first, start.second, startDir, 0, 0});

    auto blocked = [&](int x, int y)->bool{
        return x < 0 || x >= N || y < 0 || y >= M || g[x][y] == '#';
    };

    int ans = INF;

    while (!dq.empty()) {
        State cur = dq.front();
        dq.pop_front();

        int cd = dist[cur.x][cur.y][cur.dir][cur.p][cur.q];
        if (make_pair(cur.x, cur.y) == target) {
            ans = min(ans, cur.p + cur.q);
            continue;
        }

        // Move forward without placing mirror on current square
        int nx = cur.x + dx[cur.dir], ny = cur.y + dy[cur.dir];
        if (!blocked(nx, ny)) {
            if (dist[nx][ny][cur.dir][cur.p][cur.q] > cd) {
                dist[nx][ny][cur.dir][cur.p][cur.q] = cd;
                dq.push_front({nx, ny, cur.dir, cur.p, cur.q});
            }
        }

        // Place mirrors on current square if allowed (not start/target)
        if (make_pair(cur.x, cur.y) != start && make_pair(cur.x, cur.y) != target) {
            // Place P
            if (cur.p < A) {
                int nd = reflectP(cur.dir);
                int tx = cur.x + dx[nd], ty = cur.y + dy[nd];
                if (!blocked(tx, ty)) {
                    if (dist[tx][ty][nd][cur.p + 1][cur.q] > cd + 1) {
                        dist[tx][ty][nd][cur.p + 1][cur.q] = cd + 1;
                        dq.push_back({tx, ty, nd, cur.p + 1, cur.q});
                    }
                }
            }
            // Place Q
            if (cur.q < A) {
                int nd = reflectQ(cur.dir);
                int tx = cur.x + dx[nd], ty = cur.y + dy[nd];
                if (!blocked(tx, ty)) {
                    if (dist[tx][ty][nd][cur.p][cur.q + 1] > cd + 1) {
                        dist[tx][ty][nd][cur.p][cur.q + 1] = cd + 1;
                        dq.push_back({tx, ty, nd, cur.p, cur.q + 1});
                    }
                }
            }
        }
    }

    if (ans == INF) cout << "impossible\n";
    else cout << ans << "\n";

    return 0;
}

