        int M = sc.nextInt();
        int A = sc.nextInt();
        sc.nextLine();

        char[][] grid = new char[N][M];
        int sr = -1, scPos = -1, tr = -1, tc = -1;

        for (int i = 0; i < N; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < M; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    sr = i;
                    scPos = j;
                } else if (grid[i][j] == 'C') {
                    tr = i;
                    tc = j;
                }
            }
        }

        // State: (r, c, dir, usedP, usedQ)
        // dir: 0=N, 1=E, 2=S, 3=W
        int[][][][] dist = new int[N][M][4][A+1];
        for (int[][][] d1 : dist)
            for (int[][] d2 : d1)
                for (int[] d3 : d2)
                    Arrays.fill(d3, Integer.MAX_VALUE);

        Deque<int[]> dq = new ArrayDeque<>();
        // Initial: from S in all 4 directions, no mirrors used
        for (int d = 0; d < 4; d++) {
            dist[sr][scPos][d][0] = 0;
            dq.addFirst(new int[]{sr, scPos, d, 0});
        }

        int[][][] mirrorType = new int[4][2][2]; // [dir][mirrorType][newDir]
        // mirrorType 0 = P, 1 = Q
        // For each incoming direction, define the two outgoing directions
        // P mirrors: 45° (NE-SW) or 225° (SW-NE) -> reflect like '/' in standard orientation
        // Actually careful: P mirrors at 45° (/) reflect: N->E, E->N, S->W, W->S
        // Q mirrors at 135° (\) reflect: N->W, W->N, S->E, E->S
        for (int d = 0; d < 4; d++) {
            // P mirror (type 0)
            if (d == 0) { mirrorType[d][0][0] = 1; mirrorType[d][0][1] = 3; } // N -> E or W? No, only one: N->E for /
            // Actually P gives two possible orientations, so we need to handle both
        }

        // Let's redefine: For each incoming direction, P mirror (45° or 225°) gives exactly one outgoing direction.
        // 45°: N->E, E->N, S->W, W->S
        // 225°: N->W, W->N, S->E, E->S
        // So we need to try both orientations when placing a P mirror.

        while (!dq.isEmpty()) {
            int[] cur = dq.pollFirst();
            int r = cur[0], c = cur[1], dir = cur[2], usedP = cur[3];
            int usedQ = cur[4]; // Wait, we only stored usedP in dist array, need usedQ too
        }

