        // Let's redo with proper state

        // Actually simpler: use 5D array or encode state
        // Since A <= 10, we can use int[][][][][] but that's 100*100*4*11*11 ~ 4.8M, okay
        int[][][][][] distFull = new int[N][M][4][A+1][A+1];
        for (int[][][][] d1 : distFull)
            for (int[][][] d2 : d1)
                for (int[][] d3 : d2)
                    for (int[] d4 : d3)
                        Arrays.fill(d4, Integer.MAX_VALUE);

        Deque<int[]> dq2 = new ArrayDeque<>();
        for (int d = 0; d < 4; d++) {
            distFull[sr][scPos][d][0][0] = 0;
            dq2.addFirst(new int[]{sr, scPos, d, 0, 0});
        }

        int ans = Integer.MAX_VALUE;

        while (!dq2.isEmpty()) {
            int[] cur = dq2.pollFirst();
            int r = cur[0], c = cur[1], dir = cur[2], pUsed = cur[3], qUsed = cur[4];
            int d = distFull[r][c][dir][pUsed][qUsed];

            // If we reached creature, update answer
            if (r == tr && c == tc) {
                ans = Math.min(ans, d);
                continue;
            }

            // Move forward in current direction
            int nr = r + dr[dir];
            int nc = c + dc[dir];
            if (nr >= 0 && nr < N && nc >= 0 && nc < M && grid[nr][nc] != '#') {
                if (distFull[nr][nc][dir][pUsed][qUsed] > d) {
