            if (grid[r][c] != 'S' && grid[r][c] != 'C' && grid[r][c] != '#') {
                // Try P mirror (two orientations)
                if (pUsed < A) {
                    // Orientation 1: 45° (N<->E, S<->W)
                    int newDir1 = -1;
                    if (dir == 0) newDir1 = 1;
                    else if (dir == 1) newDir1 = 0;
                    else if (dir == 2) newDir1 = 3;
                    else if (dir == 3) newDir1 = 2;
                    if (newDir1 != -1 && distFull[r][c][newDir1][pUsed+1][qUsed] > d + 1) {
                        distFull[r][c][newDir1][pUsed+1][qUsed] = d + 1;
                        dq2.addLast(new int[]{r, c, newDir1, pUsed+1, qUsed});
                    }
                    // Orientation 2: 225° (N<->W, S<->E)
                    int newDir2 = -1;
                    if (dir == 0) newDir2 = 3;
                    else if (dir == 3) newDir2 = 0;
                    else if (dir == 2) newDir2 = 1;
                    else if (dir == 1) newDir2 = 2;
                    if (newDir2 != -1 && distFull[r][c][newDir2][pUsed+1][qUsed] > d + 1) {
