                // Try Q mirror (two orientations)
                if (qUsed < A) {
                    // Orientation 1: 135° (N<->W, S<->E) - same as P's 225°? No, careful
                    // Actually Q at 135°: N->W, W->N, S->E, E->S (like \)
                    int newDir1 = -1;
                    if (dir == 0) newDir1 = 3;
                    else if (dir == 3) newDir1 = 0;
                    else if (dir == 2) newDir1 = 1;
                    else if (dir == 1) newDir1 = 2;
                    if (newDir1 != -1 && distFull[r][c][newDir1][pUsed][qUsed+1] > d + 1) {
                        distFull[r][c][newDir1][pUsed][qUsed+1] = d + 1;
                        dq2.addLast(new int[]{r, c, newDir1, pUsed, qUsed+1});
                    }
                    // Orientation 2: 315° (N<->E, S<->W) - like /
                    int newDir2 = -1;
                    if (dir == 0) newDir2 = 1;
                    else if (dir == 1) newDir2 = 0;
                    else if (dir == 2) newDir2 = 3;
                    else if (dir == 3) newDir2 = 2;
                    if (newDir2 != -1 && distFull[r][c][newDir2][pUsed][qUsed+1] > d + 1) {
                        distFull[r][c][newDir2][pUsed][qUsed+1] = d + 1;
                        dq2.addLast(new int[]{r, c, newDir2, pUsed, qUsed+1});
                    }
                }
            }
        }

        if (ans == Integer.MAX_VALUE) {
            System.out.println(-1);
        } else {
            System.out.println(ans);
        }
    }
}

