import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int N, M, A;
    static char[][] grid;
    static int sx, sy, tx, ty;

    // directions: 0=up,1=right,2=down,3=left
    static int[] dx = {-1, 0, 1, 0};
    static int[] dy = {0, 1, 0, -1};

    // reflection:
    // P mirror: '/'  => up->right, right->up, down->left, left->down
    // Q mirror: '\' => up->left, left->up, down->right, right->down
    static int reflectP(int d) {
        if (d == 0) return 1;
        if (d == 1) return 0;
        if (d == 2) return 3;
        return 2;
    }

    static int reflectQ(int d) {
        if (d == 0) return 3;
        if (d == 3) return 0;
        if (d == 2) return 1;
        return 2;
    }

    static final int INF = 1_000_000_000;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        N = Integer.parseInt(first);
        M = fs.nextInt();
        A = fs.nextInt();

        grid = new char[N][M];
        sx = sy = tx = ty = -1;

        for (int i = 0; i < N; i++) {
            String s = fs.next();
            for (int j = 0; j < M; j++) {
                grid[i][j] = s.charAt(j);
                char c = grid[i][j];
                // Assume:
                // 'S' = laser generator, 'T' = creature, '#' = obstacle, others empty/passable
                if (c == 'S') {
                    sx = i;
                    sy = j;
                } else if (c == 'T') {
                    tx = i;
                    ty = j;
                }
            }
        }

        // Fallback for alternative common markers:
        if (sx == -1 || tx == -1) {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    char c = grid[i][j];
                    if (sx == -1 && (c == 'L' || c == 'G')) {
                        sx = i;
                        sy = j;
                    }
                    if (tx == -1 && (c == 'C' || c == 'E')) {
                        tx = i;
                        ty = j;
                    }
                }
            }
        }

        int ans = solve();

        if (ans == INF || ans > 2 * A) {
            System.out.println("impossible");
        } else {
            System.out.println(ans);
        }
    }

    static boolean inBounds(int x, int y) {
        return x >= 0 && x < N && y >= 0 && y < M;
    }

    static boolean blocked(int x, int y) {
        return grid[x][y] == '#';
    }

    static int solve() {
        // dist[x][y][dir][pUsed][qUsed] = min total mirrors (same as p+q, but keep for Dijkstra)
        int[][][][][] dist = new int[N][M][4][A + 1][A + 1];
        for (int i = 0; i < N; i++)
            for (int j = 0; j < M; j++)
                for (int d = 0; d < 4; d++)
                    for (int p = 0; p <= A; p++)
                        Arrays.fill(dist[i][j][d][p], INF);

        PriorityQueue<State> pq = new PriorityQueue<>();

        // initial direction can be any of 4 directions, no mirror used
        for (int d = 0; d < 4; d++) {
            dist[sx][sy][d][0][0] = 0;
            pq.add(new State(sx, sy, d, 0, 0, 0));
        }

        int best = INF;

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.cost != dist[cur.x][cur.y][cur.dir][cur.p][cur.q]) continue;
            if (cur.cost >= best) continue;

            // Move straight one cell
            int nx = cur.x + dx[cur.dir];
            int ny = cur.y + dy[cur.dir];

            if (!inBounds(nx, ny) || blocked(nx, ny)) continue;

            // Reaching target square kills creature immediately
            if (nx == tx && ny == ty) {
                best = Math.min(best, cur.cost);
            }

            // Option 1: pass through without placing mirror
            if (cur.cost < dist[nx][ny][cur.dir][cur.p][cur.q]) {
                dist[nx][ny][cur.dir][cur.p][cur.q] = cur.cost;
                pq.add(new State(nx, ny, cur.dir, cur.p, cur.q, cur.cost));
            }

            // Cannot place mirror on source or target square
            if ((nx == sx && ny == sy) || (nx == tx && ny == ty)) continue;

            // Option 2: place P mirror
            if (cur.p < A) {
                int nd = reflectP(cur.dir);
                int nc = cur.cost + 1;
                if (nc < dist[nx][ny][nd][cur.p + 1][cur.q]) {
                    dist[nx][ny][nd][cur.p + 1][cur.q] = nc;
                    pq.add(new State(nx, ny, nd, cur.p + 1, cur.q, nc));
                }
            }

            // Option 3: place Q mirror
            if (cur.q < A) {
                int nd = reflectQ(cur.dir);
                int nc = cur.cost + 1;
                if (nc < dist[nx][ny][nd][cur.p][cur.q + 1]) {
                    dist[nx][ny][nd][cur.p][cur.q + 1] = nc;
                    pq.add(new State(nx, ny, nd, cur.p, cur.q + 1, nc));
                }
            }
        }

        return best;
    }

    static class State implements Comparable<State> {
        int x, y, dir, p, q, cost;

        State(int x, int y, int dir, int p, int q, int cost) {
            this.x = x;
            this.y = y;
            this.dir = dir;
            this.p = p;
            this.q = q;
            this.cost = cost;
        }

        public int compareTo(State other) {
            return Integer.compare(this.cost, other.cost);
        }
    }
}

import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    first = data[0].split()
    if len(first) != 3:
        return
    N, M, A = map(int, first)

    grid = [list(data[i + 1].rstrip('\n')) for i in range(N)]

    # Find laser generator and creature.
    # The original statement does not specify exact symbols in this prompt,
    # so we support common possibilities.
    laser_chars = set('SL')
    target_chars = set('CT')
    obstacle_chars = set('#*X')

    laser = None
    target = None

    for i in range(N):
        for j in range(M):
            ch = grid[i][j]
            if ch in laser_chars and laser is None:
                laser = (i, j)
            elif ch in target_chars and target is None:
                target = (i, j)

    # Fallback: if symbols are different but there are exactly two non-empty special cells,
    # try to infer them from uppercase letters not recognized as obstacles.
    if laser is None or target is None:
        specials = []
        for i in range(N):
            for j in range(M):
                ch = grid[i][j]
                if ch not in obstacle_chars and ch != '.':
                    specials.append((i, j, ch))
        if len(specials) >= 2:
            if laser is None:
                laser = (specials[0][0], specials[0][1])
            if target is None:
                for x, y, _ in specials:
                    if (x, y) != laser:
                        target = (x, y)
                        break

    if laser is None or target is None:
        print("impossible")
        return

    sx, sy = laser
    tx, ty = target

    # Directions: 0=up,1=right,2=down,3=left
    dx = [-1, 0, 1, 0]
    dy = [0, 1, 0, -1]

    # Reflection rules:
    # P mirror: "/"  : up<->right, down<->left
    # Q mirror: "\" : up<->left, down<->right
    def reflect_p(d):
        return [1, 0, 3, 2][d]

    def reflect_q(d):
        return [3, 2, 1, 0][d]

    INF = 10**9
    # dist[x][y][dir][p_used][q_used] = reachable
    dist = [[[[[False] * (A + 1) for _ in range(A + 1)] for _ in range(4)] for _ in range(M)] for _ in range(N)]

    q = deque()

    # Start by emitting in any of 4 directions from the laser square.
    for d in range(4):
        dist[sx][sy][d][0][0] = True
        q.append((sx, sy, d, 0, 0))

    def is_blocked(x, y):
        return grid[x][y] in obstacle_chars

    ans = INF

    while q:
        x, y, d, p, qq = q.popleft()

        # Move forward one cell.
        nx, ny = x + dx[d], y + dy[d]
        if not (0 <= nx < N and 0 <= ny < M):
            continue
        if is_blocked(nx, ny):
            continue

        # Reaching target square kills creature immediately.
        if (nx, ny) == (tx, ty):
            ans = min(ans, p + qq)
            continue

        # Option 1: continue straight without placing mirror.
        if not dist[nx][ny][d][p][qq]:
            dist[nx][ny][d][p][qq] = True
            q.appendleft((nx, ny, d, p, qq))  # 0 additional mirrors

        # Can't place mirrors on laser or target squares.
        if (nx, ny) != (sx, sy):
            # Option 2: place P mirror if available.
            if p < A:
                nd = reflect_p(d)
                if not dist[nx][ny][nd][p + 1][qq]:
                    dist[nx][ny][nd][p + 1][qq] = True
                    q.append((nx, ny, nd, p + 1, qq))  # +1 mirror

            # Option 3: place Q mirror if available.
            if qq < A:
                nd = reflect_q(d)
                if not dist[nx][ny][nd][p][qq + 1]:
                    dist[nx][ny][nd][p][qq + 1] = True
                    q.append((nx, ny, nd, p, qq + 1))  # +1 mirror

    if ans == INF:
        print("impossible")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
